"use client";

import { type CurveFactory, curveLinear } from "d3-shape";
import { m } from "motion/react";
import { type ReactNode, useCallback, useId, useMemo } from "react";
import { useChartStable, useYScale } from "./chart-context";
import { LinePath, linePathD } from "./line-path";
import { type PatternPresetId, renderPatternPreset } from "./pattern-preset";
import {
  buildHorizontalTangentBezierPath,
  type ProjectionCurveKind,
  type ProjectionPoint,
  projectionCrossingX,
} from "./projection-utils";

export type ProjectionStrokeStyle = "solid" | "gradient";

/** Fill under the projection segment, down to the plot baseline. */
export type ProjectionAreaFill = "none" | "solid" | "gradient" | "pattern";

export interface ProjectionLineProps {
  /** Projection path points — anchor (last data row) + horizon end. */
  data: ProjectionPoint[];
  /** Y-scale group id. Default: `"left"`. */
  yAxisId?: string | number;
  /** Solid stroke color. Default: var(--chart-3) */
  stroke?: string;
  /** Solid or path-aligned gradient stroke. Default: solid */
  strokeStyle?: ProjectionStrokeStyle;
  /** Gradient start color when `strokeStyle` is gradient. Default: `stroke` */
  gradientStart?: string;
  /** Gradient end color when `strokeStyle` is gradient. Default: var(--chart-5) */
  gradientEnd?: string;
  /** Stroke width. Default: 2 */
  strokeWidth?: number;
  /** Straight segment or horizontal-tangent S-curve. Default: linear */
  curveKind?: ProjectionCurveKind;
  /** Advanced curve override (used when `curveKind` is omitted). */
  curve?: CurveFactory;
  /** Dash pattern. Default: "6,4" */
  strokeDasharray?: string;
  /** Stroke opacity. Default: 1 */
  strokeOpacity?: number;
  /** Show horizon endpoint marker. Default: true */
  showEndMarker?: boolean;
  /** @deprecated Use `showEndMarker`. */
  showEndpoints?: boolean;
  /** Endpoint marker radius. Default: 5 */
  endpointRadius?: number;
  /**
   * Horizon marker fill. Default: the end colour (a solid dot). Pass
   * `var(--background)` for a hollow ring.
   */
  endMarkerFill?: string;
  /** Print the horizon value above the end marker. Default: false */
  showEndLabel?: boolean;
  /** Formats the end label. Default: `toLocaleString()` */
  formatEndLabel?: (value: number) => string;
  /** End label colour. Default: the end colour */
  endLabelColor?: string;
  /** Fill under the projection, down to the baseline. Default: `"none"` */
  areaFill?: ProjectionAreaFill;
  /** Area colour. Default: the end colour (`gradientEnd` or `stroke`) */
  areaColor?: string;
  /** Default: 0.12 for `solid`, 0.3 for `gradient`, 0.5 for `pattern`. */
  areaOpacity?: number;
  /**
   * Fade the area out over the bottom N% of its height (0–100). Default: 100
   * for `gradient`, 0 otherwise — set it on `pattern` for a fading hatch.
   */
  areaFadeBottom?: number;
  /** Pattern preset when `areaFill` is `"pattern"`. Default: `"diagonal-up"` */
  areaPattern?: PatternPresetId;
  /** Default: 1.5 */
  areaPatternScale?: number;
  /**
   * `pattern` only — opacity of a gradient wash painted under the pattern
   * (fades out over the full height). Default: 0
   */
  areaPatternTint?: number;
  /**
   * Goal value: draws a dashed horizontal line across the plot and a marker
   * where the projection crosses it.
   */
  target?: number;
  /** Target line colour. Default: `var(--muted-foreground)` */
  targetStroke?: string;
  /** Default: `"4,4"` */
  targetDasharray?: string;
  /** Default: 0.6 */
  targetStrokeOpacity?: number;
  /** Ring on the target crossing. Default: true (when `target` is set) */
  showTargetMarker?: boolean;
  /**
   * Dashed vertical guides at the hand-off (anchor) and the target crossing.
   * Default: false
   */
  showGuides?: boolean;
  /** Guide colour. Default: `var(--muted-foreground)` */
  guideStroke?: string;
  /** Default: 0.35 */
  guideStrokeOpacity?: number;
  className?: string;
}

const ENTER_FADE = { duration: 0.42, ease: "easeOut" as const };
const LABEL_GAP = 8;
const LABEL_FONT_SIZE = 12;

function defaultAreaOpacity(areaFill: ProjectionAreaFill): number {
  if (areaFill === "pattern") {
    return 0.5;
  }
  if (areaFill === "gradient") {
    return 0.3;
  }
  return 0.12;
}

function verticalFadeStops(fadeBottom: number) {
  const zone = Math.min(100, Math.max(0, fadeBottom)) / 100;
  return [
    { offset: 0, opacity: 1 },
    { offset: 1 - zone, opacity: 1 },
    { offset: 1, opacity: zone > 0 ? 0 : 1 },
  ];
}

interface ProjectionAreaProps {
  d: string;
  uid: string;
  top: number;
  bottom: number;
  areaFill: Exclude<ProjectionAreaFill, "none">;
  color: string;
  opacity?: number;
  fadeBottom?: number;
  pattern: PatternPresetId;
  patternScale: number;
  patternTint: number;
}

function ProjectionArea({
  d,
  uid,
  top,
  bottom,
  areaFill,
  color,
  opacity,
  fadeBottom,
  pattern,
  patternScale,
  patternTint,
}: ProjectionAreaProps) {
  const resolvedOpacity = opacity ?? defaultAreaOpacity(areaFill);
  const resolvedFade = fadeBottom ?? (areaFill === "gradient" ? 100 : 0);
  const tint = areaFill === "pattern" ? patternTint : 0;
  const fadeId = `chart-projection-area-fade-${uid}`;
  const maskId = `chart-projection-area-mask-${uid}`;
  const tintId = `chart-projection-area-tint-${uid}`;
  const patternId = `chart-projection-area-pattern-${uid}`;
  const span = { gradientUnits: "userSpaceOnUse" as const, x1: 0, x2: 0 };
  const useFade = resolvedFade > 0;
  const patternNode: ReactNode =
    areaFill === "pattern"
      ? renderPatternPreset(pattern, patternId, {
          color,
          scale: patternScale,
        })
      : null;

  let fill = color;
  if (areaFill === "pattern" && patternNode) {
    fill = `url(#${patternId})`;
  }

  return (
    <>
      <defs>
        {useFade ? (
          <>
            <linearGradient id={fadeId} {...span} y1={top} y2={bottom}>
              {verticalFadeStops(resolvedFade).map((stop) => (
                <stop
                  key={stop.offset}
                  offset={stop.offset}
                  stopColor="white"
                  stopOpacity={stop.opacity}
                />
              ))}
            </linearGradient>
            <mask id={maskId} maskUnits="userSpaceOnUse">
              <path d={d} fill={`url(#${fadeId})`} />
            </mask>
          </>
        ) : null}
        {tint > 0 ? (
          <linearGradient id={tintId} {...span} y1={top} y2={bottom}>
            <stop offset={0} stopColor={color} stopOpacity={tint} />
            <stop offset={1} stopColor={color} stopOpacity={0} />
          </linearGradient>
        ) : null}
      </defs>
      {patternNode}
      {tint > 0 ? <path d={d} fill={`url(#${tintId})`} /> : null}
      <path
        d={d}
        fill={fill}
        mask={useFade ? `url(#${maskId})` : undefined}
        opacity={resolvedOpacity}
      />
    </>
  );
}

function resolveVisibleEndX(
  endX: number,
  innerWidth: number,
  endpointRadius: number,
  strokeWidth: number
): number {
  const edgePadding = endpointRadius + strokeWidth * 0.5 + 1;
  return Math.min(endX, Math.max(0, innerWidth - edgePadding));
}

function renderProjectionStroke({
  bezierPath,
  curve,
  curveKind,
  data,
  getX,
  getY,
  linearPath,
  strokeProps,
}: {
  bezierPath: string | null;
  curve: CurveFactory | undefined;
  curveKind: ProjectionCurveKind;
  data: ProjectionPoint[];
  getX: (point: ProjectionPoint) => number;
  getY: (point: ProjectionPoint) => number;
  linearPath: string | null;
  strokeProps: {
    stroke: string;
    strokeDasharray: string;
    strokeLinecap: "round";
    strokeOpacity: number;
    strokeWidth: number;
  };
}) {
  if (curveKind === "bezier" && bezierPath) {
    return <path d={bezierPath} fill="none" {...strokeProps} />;
  }
  if (curveKind === "linear" && linearPath) {
    return <path d={linearPath} fill="none" {...strokeProps} />;
  }
  return (
    <LinePath
      d={linePathD(data, { curve: curve ?? curveLinear, x: getX, y: getY })}
      {...strokeProps}
    />
  );
}

interface ProjectionGeometry {
  startX: number;
  startY: number;
  visibleEndX: number;
  endY: number;
}

function useProjectionGeometry({
  data,
  yAxisId,
  showMarker,
  endpointRadius,
  strokeWidth,
}: {
  data: ProjectionPoint[];
  yAxisId: string | number | undefined;
  showMarker: boolean;
  endpointRadius: number;
  strokeWidth: number;
}) {
  const { xScale, innerWidth } = useChartStable();
  const yScale = useYScale(yAxisId);

  const getX = useCallback(
    (point: ProjectionPoint) => xScale(point.date) ?? 0,
    [xScale]
  );
  const getY = useCallback(
    (point: ProjectionPoint) => yScale(point.value) ?? 0,
    [yScale]
  );

  const startPoint = data[0];
  const endPoint = data.at(-1);

  const geometry = useMemo<ProjectionGeometry | null>(() => {
    if (!(startPoint && endPoint)) {
      return null;
    }
    return {
      startX: getX(startPoint),
      startY: getY(startPoint),
      visibleEndX: resolveVisibleEndX(
        getX(endPoint),
        innerWidth,
        showMarker ? endpointRadius : 0,
        strokeWidth
      ),
      endY: getY(endPoint),
    };
  }, [
    endPoint,
    endpointRadius,
    getX,
    getY,
    innerWidth,
    showMarker,
    startPoint,
    strokeWidth,
  ]);

  return { geometry, getX, getY, yScale };
}

function projectionSegmentPaths(
  geometry: ProjectionGeometry | null,
  curveKind: ProjectionCurveKind
) {
  if (!geometry) {
    return { bezierPath: null, linearPath: null, topPath: null };
  }
  const { startX, startY, visibleEndX, endY } = geometry;
  const linear = `M ${startX},${startY} L ${visibleEndX},${endY}`;
  const bezierPath =
    curveKind === "bezier"
      ? buildHorizontalTangentBezierPath(startX, startY, visibleEndX, endY)
      : null;
  return {
    bezierPath,
    linearPath: curveKind === "linear" ? linear : null,
    topPath: bezierPath ?? linear,
  };
}

function ProjectionTargetOverlay({
  geometry,
  targetY,
  crossingX,
  color,
  markerRadius,
  endpointRadius,
  markerFill,
  showTargetMarker,
  showGuides,
  targetStroke,
  targetDasharray,
  targetStrokeOpacity,
  guideStroke,
  guideStrokeOpacity,
}: {
  geometry: ProjectionGeometry;
  targetY: number | null;
  crossingX: number | null;
  color: string;
  markerRadius: number;
  endpointRadius: number;
  markerFill: string;
  showTargetMarker: boolean;
  showGuides: boolean;
  targetStroke: string;
  targetDasharray: string;
  targetStrokeOpacity: number;
  guideStroke: string;
  guideStrokeOpacity: number;
}) {
  const { innerWidth, innerHeight } = useChartStable();
  const targetInPlot =
    targetY != null && targetY >= 0 && targetY <= innerHeight;
  const crossing =
    crossingX != null && targetY != null ? { x: crossingX, y: targetY } : null;
  const guideXs = [geometry.startX, ...(crossing ? [crossing.x] : [])];

  return (
    <>
      {showGuides
        ? guideXs.map((x) => (
            <line
              key={x}
              stroke={guideStroke}
              strokeDasharray="3,3"
              strokeOpacity={guideStrokeOpacity}
              x1={x}
              x2={x}
              y1={0}
              y2={innerHeight}
            />
          ))
        : null}
      {targetInPlot ? (
        <line
          stroke={targetStroke}
          strokeDasharray={targetDasharray}
          strokeOpacity={targetStrokeOpacity}
          x1={0}
          x2={innerWidth}
          y1={targetY}
          y2={targetY}
        />
      ) : null}
      {showTargetMarker && crossing ? (
        <g className="chart-projection-target-marker">
          <circle
            cx={crossing.x}
            cy={crossing.y}
            fill={color}
            opacity={0.18}
            r={endpointRadius * 2}
          />
          <circle
            cx={crossing.x}
            cy={crossing.y}
            fill={markerFill}
            r={markerRadius}
            stroke={color}
            strokeWidth={1.5}
          />
        </g>
      ) : null}
    </>
  );
}

function ProjectionHorizon({
  x,
  y,
  value,
  color,
  radius,
  fill,
  fillOpacity,
  showMarker,
  showLabel,
  formatLabel,
  labelColor,
}: {
  x: number;
  y: number;
  value: number;
  color: string;
  radius: number;
  fill: string | undefined;
  fillOpacity: number;
  showMarker: boolean;
  showLabel: boolean;
  formatLabel?: (value: number) => string;
  labelColor?: string;
}) {
  const hollow = fill != null;
  const labelBelow = y < radius + LABEL_GAP + LABEL_FONT_SIZE;
  return (
    <>
      {showMarker ? (
        <circle
          cx={x}
          cy={y}
          fill={fill ?? color}
          fillOpacity={fillOpacity}
          r={radius}
          stroke={hollow ? color : undefined}
          strokeWidth={hollow ? 1.5 : undefined}
        />
      ) : null}
      {showLabel ? (
        <text
          dominantBaseline={labelBelow ? "hanging" : "auto"}
          fill={labelColor ?? color}
          fontSize={LABEL_FONT_SIZE}
          fontWeight={600}
          style={{ fontVariantNumeric: "tabular-nums" }}
          textAnchor="end"
          x={x + radius}
          y={labelBelow ? y + radius + LABEL_GAP : y - radius - LABEL_GAP}
        >
          {formatLabel ? formatLabel(value) : value.toLocaleString()}
        </text>
      ) : null}
    </>
  );
}

export function ProjectionLine({
  data,
  yAxisId,
  stroke = "var(--chart-3)",
  strokeStyle = "solid",
  gradientStart,
  gradientEnd = "var(--chart-5)",
  strokeWidth = 2,
  curveKind = "linear",
  curve,
  strokeDasharray = "6,4",
  strokeOpacity = 1,
  showEndMarker,
  showEndpoints,
  endpointRadius = 5,
  endMarkerFill,
  showEndLabel = false,
  formatEndLabel,
  endLabelColor,
  areaFill = "none",
  areaColor,
  areaOpacity,
  areaFadeBottom,
  areaPattern = "diagonal-up",
  areaPatternScale = 1.5,
  areaPatternTint = 0,
  target,
  targetStroke = "var(--muted-foreground)",
  targetDasharray = "4,4",
  targetStrokeOpacity = 0.6,
  showTargetMarker = true,
  showGuides = false,
  guideStroke = "var(--muted-foreground)",
  guideStrokeOpacity = 0.35,
  className,
}: ProjectionLineProps) {
  const { chartPhase, innerHeight } = useChartStable();
  const gradientId = useId().replace(/:/g, "");
  const showMarker = showEndMarker ?? showEndpoints ?? true;
  const isGradient = strokeStyle === "gradient";

  const { geometry, getX, getY, yScale } = useProjectionGeometry({
    data,
    yAxisId,
    showMarker,
    endpointRadius,
    strokeWidth,
  });

  const { bezierPath, linearPath, topPath } = useMemo(
    () => projectionSegmentPaths(geometry, curveKind),
    [curveKind, geometry]
  );

  const targetY =
    target != null && Number.isFinite(target) ? (yScale(target) ?? null) : null;

  const crossingX = useMemo(
    () =>
      geometry && targetY != null
        ? projectionCrossingX(
            geometry.startX,
            geometry.startY,
            geometry.visibleEndX,
            geometry.endY,
            targetY,
            curveKind
          )
        : null,
    [curveKind, geometry, targetY]
  );

  const showStroke =
    chartPhase === "revealing" ||
    chartPhase === "ready" ||
    chartPhase === "exitingReady";

  if (data.length < 2 || !geometry) {
    return null;
  }

  const endColor = isGradient ? gradientEnd : stroke;
  const markerRadius = endpointRadius * 0.85;
  const strokeProps = {
    stroke: isGradient ? `url(#${gradientId})` : stroke,
    strokeDasharray,
    strokeLinecap: "round" as const,
    strokeOpacity,
    strokeWidth,
  };

  return (
    <m.g
      animate={{ opacity: showStroke ? 1 : 0 }}
      className={className ?? "chart-projection-line"}
      initial={{ opacity: 0 }}
      transition={ENTER_FADE}
    >
      {isGradient ? (
        <defs>
          <linearGradient
            gradientUnits="userSpaceOnUse"
            id={gradientId}
            x1={geometry.startX}
            x2={geometry.visibleEndX}
            y1={geometry.startY}
            y2={geometry.endY}
          >
            <stop offset="0%" stopColor={gradientStart ?? stroke} />
            <stop offset="100%" stopColor={gradientEnd} />
          </linearGradient>
        </defs>
      ) : null}
      {areaFill !== "none" && topPath ? (
        <ProjectionArea
          areaFill={areaFill}
          bottom={innerHeight}
          color={areaColor ?? endColor}
          d={`${topPath} L ${geometry.visibleEndX},${innerHeight} L ${geometry.startX},${innerHeight} Z`}
          fadeBottom={areaFadeBottom}
          opacity={areaOpacity}
          pattern={areaPattern}
          patternScale={areaPatternScale}
          patternTint={areaPatternTint}
          top={Math.min(geometry.startY, geometry.endY)}
          uid={gradientId}
        />
      ) : null}
      <ProjectionTargetOverlay
        color={endColor}
        crossingX={crossingX}
        endpointRadius={endpointRadius}
        geometry={geometry}
        guideStroke={guideStroke}
        guideStrokeOpacity={guideStrokeOpacity}
        markerFill={endMarkerFill ?? "var(--background)"}
        markerRadius={markerRadius}
        showGuides={showGuides}
        showTargetMarker={showTargetMarker}
        targetDasharray={targetDasharray}
        targetStroke={targetStroke}
        targetStrokeOpacity={targetStrokeOpacity}
        targetY={targetY}
      />
      {renderProjectionStroke({
        bezierPath,
        curve,
        curveKind,
        data,
        getX,
        getY,
        linearPath,
        strokeProps,
      })}
      <ProjectionHorizon
        color={endColor}
        fill={endMarkerFill}
        fillOpacity={strokeOpacity}
        formatLabel={formatEndLabel}
        labelColor={endLabelColor}
        radius={markerRadius}
        showLabel={showEndLabel}
        showMarker={showMarker}
        value={data.at(-1)?.value ?? 0}
        x={geometry.visibleEndX}
        y={geometry.endY}
      />
    </m.g>
  );
}

ProjectionLine.displayName = "ProjectionLine";

export default ProjectionLine;

"use client";

import { useCallback } from "react";
import { useChartStable, useYScale } from "./chart-context";
import type { ProjectionPoint } from "./projection-utils";

export interface ProjectionLineEndMarkerProps {
  data: ProjectionPoint[];
  yAxisId?: string | number;
  stroke?: string;
  strokeOpacity?: number;
  radius?: number;
}

/** Renders the projection horizon dot outside the series reveal clip. */
export function ProjectionLineEndMarker({
  data,
  yAxisId,
  stroke = "var(--chart-3)",
  strokeOpacity = 1,
  radius = 5,
}: ProjectionLineEndMarkerProps) {
  const { xScale, chartPhase, innerWidth } = useChartStable();
  const yScale = useYScale(yAxisId);

  const getX = useCallback(
    (point: ProjectionPoint) => xScale(point.date) ?? 0,
    [xScale]
  );
  const getY = useCallback(
    (point: ProjectionPoint) => yScale(point.value) ?? 0,
    [yScale]
  );

  const showStroke =
    chartPhase === "revealing" ||
    chartPhase === "ready" ||
    chartPhase === "exitingReady";

  if (!showStroke || data.length < 2) {
    return null;
  }

  const endPoint = data.at(-1);
  if (!endPoint) {
    return null;
  }
  const edgePadding = radius + 1;
  const endX = Math.min(getX(endPoint), Math.max(0, innerWidth - edgePadding));
  const endY = getY(endPoint);

  return (
    <circle
      cx={endX}
      cy={endY}
      fill={stroke}
      fillOpacity={strokeOpacity}
      r={radius * 0.85}
    />
  );
}

ProjectionLineEndMarker.displayName = "ProjectionLineEndMarker";

(
  ProjectionLineEndMarker as unknown as Record<string, boolean>
).__isPostOverlay = true;

export default ProjectionLineEndMarker;

export type ProjectionMode = "auto" | "target" | "manual";
export type ProjectionAutoMethod = "linearRegression" | "lastSegment";
/** How the projection segment is drawn between anchor and horizon. */
export type ProjectionCurveKind = "linear" | "bezier";
/** @deprecated Stepped density removed — projections always anchor → horizon. */
export type ProjectionPathDensity = "stepped" | "endpoints";

export interface ProjectionPoint {
  date: Date;
  value: number;
}

export interface BuildProjectionPathOptions {
  sourceData: Record<string, unknown>[];
  seriesKey: string;
  xDataKey?: string;
  mode: ProjectionMode;
  autoMethod?: ProjectionAutoMethod;
  /** Auto mode: stepped points per interval, or anchor + end only. Default: stepped */
  pathDensity?: ProjectionPathDensity;
  /** Index in sourceData where projection anchors (default: last point). */
  startIndex?: number;
  /** How many future points to generate (matches source cadence). */
  horizonPoints?: number;
  /** Target Y at the final projected date (target mode). */
  endValue?: number;
  /** Full manual path — anchor + future points (manual mode). */
  points?: ProjectionPoint[];
}

function readDate(row: Record<string, unknown>, xDataKey: string): Date | null {
  const raw = row[xDataKey];
  if (raw instanceof Date && !Number.isNaN(raw.getTime())) {
    return raw;
  }
  if (typeof raw === "number" && Number.isFinite(raw)) {
    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  if (typeof raw === "string") {
    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  return null;
}

function readValue(
  row: Record<string, unknown>,
  seriesKey: string
): number | null {
  const raw = row[seriesKey];
  return typeof raw === "number" && Number.isFinite(raw) ? raw : null;
}

function resolveStartIndex(
  sourceData: Record<string, unknown>[],
  startIndex: number | undefined
): number {
  if (startIndex == null || !Number.isFinite(startIndex)) {
    return Math.max(0, sourceData.length - 1);
  }
  return Math.min(Math.max(0, Math.floor(startIndex)), sourceData.length - 1);
}

function intervalFromAdjacentRows(
  sourceData: Record<string, unknown>[],
  xDataKey: string,
  startIndex: number
): number | null {
  if (startIndex < 1) {
    return null;
  }
  const prevRow = sourceData[startIndex - 1];
  const currentRow = sourceData[startIndex];
  const prev = prevRow ? readDate(prevRow, xDataKey) : null;
  const current = currentRow ? readDate(currentRow, xDataKey) : null;
  if (!(prev && current)) {
    return null;
  }
  const delta = current.getTime() - prev.getTime();
  return delta > 0 ? delta : null;
}

function intervalFromSeriesSpan(
  sourceData: Record<string, unknown>[],
  xDataKey: string
): number | null {
  if (sourceData.length < 2) {
    return null;
  }
  const firstRow = sourceData[0];
  const lastRow = sourceData.at(-1);
  const first = firstRow ? readDate(firstRow, xDataKey) : null;
  const last = lastRow ? readDate(lastRow, xDataKey) : null;
  if (!(first && last)) {
    return null;
  }
  const span = last.getTime() - first.getTime();
  return span > 0 ? span / (sourceData.length - 1) : null;
}

function resolveIntervalMs(
  sourceData: Record<string, unknown>[],
  xDataKey: string,
  startIndex: number
): number {
  return (
    intervalFromAdjacentRows(sourceData, xDataKey, startIndex) ??
    intervalFromSeriesSpan(sourceData, xDataKey) ??
    86_400_000
  );
}

function linearRegressionSlope(points: { t: number; y: number }[]): number {
  if (points.length < 2) {
    return 0;
  }
  const n = points.length;
  let sumT = 0;
  let sumY = 0;
  let sumTY = 0;
  let sumTT = 0;
  for (const { t, y } of points) {
    sumT += t;
    sumY += y;
    sumTY += t * y;
    sumTT += t * t;
  }
  const denom = n * sumTT - sumT * sumT;
  if (Math.abs(denom) < 1e-12) {
    return 0;
  }
  return (n * sumTY - sumT * sumY) / denom;
}

function buildAutoFutureValues(options: {
  anchorTime: number;
  anchorValue: number;
  autoMethod: ProjectionAutoMethod;
  historyPoints: { t: number; y: number }[];
  horizonPoints: number;
  intervalMs: number;
  pathDensity: ProjectionPathDensity;
}): ProjectionPoint[] {
  const {
    anchorTime,
    anchorValue,
    autoMethod,
    historyPoints,
    horizonPoints,
    intervalMs,
    pathDensity,
  } = options;

  const slope =
    autoMethod === "lastSegment" && historyPoints.length >= 2
      ? (() => {
          const prev = historyPoints.at(-2);
          const last = historyPoints.at(-1);
          if (!(prev && last)) {
            return 0;
          }
          const dt = last.t - prev.t;
          return dt === 0 ? 0 : (last.y - prev.y) / dt;
        })()
      : linearRegressionSlope(historyPoints);

  if (pathDensity === "endpoints") {
    const endTime = anchorTime + intervalMs * horizonPoints;
    const endValue = anchorValue + slope * intervalMs * horizonPoints;
    return [
      { date: new Date(anchorTime), value: anchorValue },
      { date: new Date(endTime), value: endValue },
    ];
  }

  const result: ProjectionPoint[] = [
    { date: new Date(anchorTime), value: anchorValue },
  ];

  for (let i = 1; i <= horizonPoints; i++) {
    const t = anchorTime + intervalMs * i;
    const value = anchorValue + slope * intervalMs * i;
    result.push({ date: new Date(t), value });
  }

  return result;
}

/** Slope (value change per ms) at the projection anchor from the last data segment. */
export function computeProjectionAnchorTangentSlope(
  sourceData: Record<string, unknown>[],
  seriesKey: string,
  xDataKey = "date",
  startIndexProp?: number
): number {
  if (sourceData.length < 2) {
    return 0;
  }
  const startIndex = resolveStartIndex(sourceData, startIndexProp);
  const historyPoints: { t: number; y: number }[] = [];
  for (let i = 0; i <= startIndex; i++) {
    const row = sourceData[i];
    if (!row) {
      continue;
    }
    const date = readDate(row, xDataKey);
    const value = readValue(row, seriesKey);
    if (date && value != null) {
      historyPoints.push({ t: date.getTime(), y: value });
    }
  }
  if (historyPoints.length < 2) {
    return 0;
  }
  const prev = historyPoints.at(-2);
  const last = historyPoints.at(-1);
  if (!(prev && last)) {
    return 0;
  }
  const dt = last.t - prev.t;
  return dt === 0 ? 0 : (last.y - prev.y) / dt;
}

/** Cubic bezier with horizontal tangents at start and end (price-target S-curve). */
export function buildHorizontalTangentBezierPath(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  /** How far control points sit along the x span (0–0.5). Default: 0.45 */
  tension = 0.45
): string {
  const dx = x1 - x0;
  if (Math.abs(dx) < 1e-6) {
    return `M ${x0},${y0} L ${x1},${y1}`;
  }
  const t = Math.min(0.5, Math.max(0.05, tension));
  const c1x = x0 + dx * t;
  const c2x = x1 - dx * t;
  return `M ${x0},${y0} C ${c1x},${y0} ${c2x},${y1} ${x1},${y1}`;
}

/**
 * Pixel x where a projection segment crosses `targetY`, or `null` when the
 * target lies outside the segment. Matches both `curveKind`s: a straight
 * line, or the horizontal-tangent bezier from
 * {@link buildHorizontalTangentBezierPath} (monotonic in y, so the crossing
 * is found by bisection).
 */
export function projectionCrossingX(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  targetY: number,
  curveKind: ProjectionCurveKind = "linear",
  tension = 0.45
): number | null {
  const lo = Math.min(y0, y1);
  const hi = Math.max(y0, y1);
  if (!Number.isFinite(targetY) || targetY < lo || targetY > hi) {
    return null;
  }
  if (Math.abs(y1 - y0) < 1e-9) {
    return x0;
  }
  const dx = x1 - x0;
  if (curveKind === "linear" || Math.abs(dx) < 1e-6) {
    return x0 + (dx * (targetY - y0)) / (y1 - y0);
  }
  const k = Math.min(0.5, Math.max(0.05, tension));
  // Control points: (x0 + dx·k, y0) and (x1 − dx·k, y1).
  const bezier = (t: number, a: number, b: number, c: number, d: number) => {
    const u = 1 - t;
    return (
      u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * d
    );
  };
  const rising = y1 > y0;
  let tLo = 0;
  let tHi = 1;
  for (let step = 0; step < 40; step++) {
    const mid = (tLo + tHi) / 2;
    const y = bezier(mid, y0, y0, y1, y1);
    if (y < targetY === rising) {
      tLo = mid;
    } else {
      tHi = mid;
    }
  }
  const t = (tLo + tHi) / 2;
  return bezier(t, x0, x0 + dx * k, x1 - dx * k, x1);
}

function buildTargetPath(options: {
  anchorTime: number;
  anchorValue: number;
  endValue: number;
  horizonPoints: number;
  intervalMs: number;
}): ProjectionPoint[] {
  const { anchorTime, anchorValue, endValue, horizonPoints, intervalMs } =
    options;
  const endTime = anchorTime + intervalMs * horizonPoints;
  return [
    { date: new Date(anchorTime), value: anchorValue },
    { date: new Date(endTime), value: endValue },
  ];
}

/** Build a projection path from historical chart data or explicit points. */
export function buildProjectionPath(
  options: BuildProjectionPathOptions
): ProjectionPoint[] {
  const {
    sourceData,
    seriesKey,
    xDataKey = "date",
    mode,
    autoMethod = "linearRegression",
    pathDensity = "endpoints",
    startIndex: startIndexProp,
    horizonPoints = 6,
    endValue,
    points,
  } = options;

  if (mode === "manual" && points && points.length >= 2) {
    return points.map((point) => ({
      date: new Date(point.date),
      value: point.value,
    }));
  }

  if (sourceData.length === 0) {
    return [];
  }

  const startIndex = resolveStartIndex(sourceData, startIndexProp);
  const anchorRow = sourceData[startIndex];
  if (!anchorRow) {
    return [];
  }

  const anchorDate = readDate(anchorRow, xDataKey);
  const anchorValue = readValue(anchorRow, seriesKey);
  if (!anchorDate || anchorValue == null) {
    return [];
  }

  const intervalMs = resolveIntervalMs(sourceData, xDataKey, startIndex);
  const anchorTime = anchorDate.getTime();

  const historyPoints: { t: number; y: number }[] = [];
  for (let i = 0; i <= startIndex; i++) {
    const row = sourceData[i];
    if (!row) {
      continue;
    }
    const date = readDate(row, xDataKey);
    const value = readValue(row, seriesKey);
    if (date && value != null) {
      historyPoints.push({ t: date.getTime(), y: value });
    }
  }

  if (mode === "target" && endValue != null && Number.isFinite(endValue)) {
    return buildTargetPath({
      anchorTime,
      anchorValue,
      endValue,
      horizonPoints,
      intervalMs,
    });
  }

  return buildAutoFutureValues({
    anchorTime,
    anchorValue,
    autoMethod,
    historyPoints,
    horizonPoints,
    intervalMs,
    pathDensity,
  });
}

/** Collect numeric Y extents from projection point arrays. */
export function projectionValueExtents(
  paths: ProjectionPoint[][]
): { minValue: number; maxValue: number } | null {
  let minValue = Number.POSITIVE_INFINITY;
  let maxValue = Number.NEGATIVE_INFINITY;

  for (const path of paths) {
    for (const point of path) {
      if (point.value < minValue) {
        minValue = point.value;
      }
      if (point.value > maxValue) {
        maxValue = point.value;
      }
    }
  }

  if (minValue === Number.POSITIVE_INFINITY) {
    return null;
  }

  return { minValue, maxValue };
}

/** Collect date extents from projection point arrays. */
export function projectionDateExtents(
  paths: ProjectionPoint[][]
): { minTime: number; maxTime: number } | null {
  let minTime = Number.POSITIVE_INFINITY;
  let maxTime = Number.NEGATIVE_INFINITY;

  for (const path of paths) {
    for (const point of path) {
      const time = point.date.getTime();
      if (time < minTime) {
        minTime = time;
      }
      if (time > maxTime) {
        maxTime = time;
      }
    }
  }

  if (minTime === Number.POSITIVE_INFINITY) {
    return null;
  }

  return { minTime, maxTime };
}

"use client";

import { m } from "motion/react";
import { useMemo } from "react";
import { useChartStable, useYScale } from "./chart-context";
import { StaticSeriesPointMarker } from "./series-point-marker";

export interface LineSeriesTerminalMarkerProps {
  dataKey: string;
  yAxisId?: string | number;
  /** Dot fill. Default: `stroke`. */
  fill?: string;
  stroke?: string;
  radius?: number;
  ringGap?: number;
  strokeWidth?: number;
}

function isTerminalMarkerPhaseVisible(phase: string): boolean {
  return phase === "ready" || phase === "exitingReady";
}

/**
 * Dot (and, with `ringGap`, a ring) at the last data point — the anchor for
 * projection lines. `fill` defaults to `stroke`; pass `"transparent"` for a
 * hollow marker.
 */
export function LineSeriesTerminalMarker({
  dataKey,
  yAxisId,
  fill,
  stroke = "var(--chart-1)",
  radius = 5,
  ringGap = 0,
  strokeWidth = 1.5,
}: LineSeriesTerminalMarkerProps) {
  const { data, xScale, xAccessor, chartPhase, revealEpoch, enterTransition } =
    useChartStable();
  const yScale = useYScale(yAxisId);

  const point = useMemo(() => {
    const lastRow = data.at(-1);
    if (!lastRow) {
      return null;
    }
    const value = lastRow[dataKey];
    if (typeof value !== "number") {
      return null;
    }
    return {
      cx: xScale(xAccessor(lastRow)) ?? 0,
      cy: yScale(value) ?? 0,
    };
  }, [data, dataKey, xAccessor, xScale, yScale]);

  const visible = isTerminalMarkerPhaseVisible(chartPhase);
  const fadeTransition =
    enterTransition && typeof enterTransition === "object"
      ? enterTransition
      : { duration: 0.28, ease: [0.22, 1, 0.36, 1] as const };

  if (!point) {
    return null;
  }

  return (
    <m.g
      animate={{
        opacity: visible ? 1 : 0,
        scale: visible ? 1 : 0.55,
      }}
      initial={{ opacity: 0, scale: 0.55 }}
      key={revealEpoch ?? 0}
      style={{
        transformBox: "fill-box" as const,
        transformOrigin: `${point.cx}px ${point.cy}px`,
      }}
      transition={fadeTransition}
    >
      <StaticSeriesPointMarker
        cx={point.cx}
        cy={point.cy}
        fill={fill ?? stroke}
        radius={radius}
        ringGap={ringGap}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    </m.g>
  );
}

LineSeriesTerminalMarker.displayName = "LineSeriesTerminalMarker";

(
  LineSeriesTerminalMarker as unknown as Record<string, boolean>
).__isPostOverlay = true;

export default LineSeriesTerminalMarker;
